#include <string>
#include <algorithm>

class Solution {
public:
    int maxDiff(int num) {
        std::string s = std::to_string(num);
        std::string maxS = s;
        for (char ch : s) {
            if (ch != '9') {
                for (char& c : maxS) if (c == ch) c = '9';
                break;
            }
        }
        std::string minS = s;
        if (s[0] != '1') {
            char target = s[0];
            for (char& c : minS) if (c == target) c = '1';
        } else {
            for (int i = 1; i < (int)s.size(); ++i) {
                if (s[i] != '0' && s[i] != '1') {
                    char target = s[i];
                    for (char& c : minS) if (c == target) c = '0';
                    break;
                }
            }
        }
        return std::stoi(maxS) - std::stoi(minS);
    }
};

class Solution {
    public int maxDiff(int num) {
        String s = Integer.toString(num);
        String maxS = s;
        for (char ch : s.toCharArray()) {
            if (ch != '9') {
                maxS = s.replace(ch, '9');
                break;
            }
        }
        String minS = s;
        if (s.charAt(0) != '1') {
            minS = s.replace(s.charAt(0), '1');
        } else {
            for (int i = 1; i < s.length(); i++) {
                char ch = s.charAt(i);
                if (ch != '0' && ch != '1') {
                    minS = s.replace(ch, '0');
                    break;
                }
            }
        }
        return Integer.parseInt(maxS) - Integer.parseInt(minS);
    }
}

var maxDiff = function(num) {
    const s = num.toString();
    let maxS = s;
    for (const ch of s) {
        if (ch !== '9') {
            maxS = s.replaceAll(ch, '9');
            break;
        }
    }
    let minS = s;
    if (s[0] !== '1') {
        minS = s.replaceAll(s[0], '1');
    } else {
        for (let i = 1; i < s.length; i++) {
            if (s[i] !== '0' && s[i] !== '1') {
                minS = s.replaceAll(s[i], '0');
                break;
            }
        }
    }
    return parseInt(maxS, 10) - parseInt(minS, 10);
};
